sys_ui_action.script:
function confirmStartDeletion() {
    var gm = new GlideModal('', false, 700);
    gm.setTitle('Confirm workload deletion');

    top.window.startWorkloadDeletionConfirm = function(answer) {
        gm.destroy();

        if (answer === 'yes') {
            gsftSubmit(null, g_form.getFormElement(), 'start_workload_deletion');
        }

        return false;
    };

    var html =
        '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
            '<p>Are you sure you want to start the deletion process? This will delete/unpair workloads matched by active deletion sync filters.</p>' +
            '<p>It is recommended to run the following in order before proceeding:<br>' +
            '1. Data Collection - To discover the latest state workloads.<br>' +
            '2. Preview workload deletion - To verify all workloads.</p>' +
            '<p><b>Deletion is a non-reversible action.</b> Click "Yes" to proceed.</p>' +
            '<div style="display:flex; justify-content:flex-end; gap:12px; margin-top:20px;">' +
                '<button style="flex: 1; width: 100%" class="btn btn-default" onclick="top.window.startWorkloadDeletionConfirm(\'no\'); return false;">Cancel</button>' +
                '<button style="flex: 1; width: 100%" class="btn btn-danger" onclick="top.window.startWorkloadDeletionConfirm(\'yes\'); return false;">Yes</button>' +
            '</div>' +
        '</div>';

    gm.renderWithContent(html);
    return false;
}

// Server half: a trigger, and nothing else.
//
// This used to run both phases of the deletion inline -- getEligibleWorkloadSysIdsByConfig, then
// prepareWorkloadsForPCE over every match, writing payload rows -- and only create the scheduled job
// once all of that had finished. On a configuration of any size that is minutes of work inside a
// browser request, and it put the running-job guard after the work it was meant to prevent.
//
// Deletion is a job now, exactly like sync: this validates, creates the job record, raises the
// event and returns. IllumioStartWorkloadDeletion does the work in the scheduler and reports
// progress on the job record.
if (typeof window === 'undefined') {
    // Declared inside the server guard for the same reason gs.include is: this Script
    // field is evaluated in the browser too, for the client half above, and IllumioLogger
    // is a server Script Include. At the top of the file it threw a ReferenceError on
    // every form load and stopped the form rendering.
    var illumioLogger = new IllumioLogger(null, 'Start Workload Deletion');

    // Inside the server guard, not at the top of the file. This Script field is evaluated in
    // the browser too, for the client half above, and `gs` does not exist there -- a
    // top-level gs.include would throw a ReferenceError and kill the onclick handler.
    gs.include("IllumioConstants");

    var configSysId = current.getUniqueValue();
    var redirectUrl = current.getTableName() + '.do?sys_id=' + configSysId;

    try {
        var utils = new IllumioUtils();
        // Scoped to this PCE Configuration. It was instance-wide, which was propping up two
        // sweeps that deleted anything they did not own -- both fixed, see getRunningJob.
        var runningJob = utils.getRunningJob(configSysId);

        var previewStatus = utils.deletionPreviewStatus(configSysId);

        if (!previewStatus.fresh) {
            // Says which of the several reasons it is. The old message was one sentence for all
            // of them, so a preview that went to a Sync Filter, a preview job still in flight and
            // a genuinely stale file all read identically -- and the first two look to the user
            // like the gate is simply wrong.
            gs.addErrorMessage(utils.describeDeletionPreviewRefusal(previewStatus));
            action.setRedirectURL(redirectUrl);

        } else if (runningJob) {
            // Now genuinely a guard: nothing has been queried or written at this point.
            //
            // Widened from "another job on this PCE Configuration" to "another Illumio job
            // anywhere", which is the rule the preview export introduced and which this one is
            // now a case of. The narrower version was never really per-configuration in effect:
            // deletion and sync both write to the shared payload tables and both drive the same
            // MID Server, so two configurations running at once were already contending.
            gs.addErrorMessage(utils.describeRunningJob(runningJob));
            action.setRedirectURL(redirectUrl);

        } else {
            var jobGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
            jobGr.initialize();
            jobGr.job_owner = gs.getUser().getID();
            jobGr.job_type = 'deletion';
            jobGr.job_status = 'running';
            jobGr.job_started = new GlideDateTime();
            jobGr.current_operation = 'Preparing workload deletion';
            jobGr.illumio_pce_configuration = configSysId;
            jobGr.logs = 'Deletion requested. Resolving deletion sync filters.';
            var jobSysId = jobGr.insert();
            // From here on the job record exists, so anything this action logs -- including
            // an exception out of the block below -- lands under the same job id the
            // scheduler half will use.
            illumioLogger.setContext(jobSysId);

            if (gs.nil(jobSysId)) {
                gs.addErrorMessage('Failed to create scheduled job for deletion.');
            } else {
                // Same handoff discovery uses to reach its own long-running work: the event is
                // raised here, the Script Action picks it up in the scheduler.
                gs.eventQueueScheduled('x_illu2_illumio.start_workload_deletion',
                    jobGr, jobSysId, '', new GlideDateTime());

                gs.addInfoMessage('Deletion job started. Track progress in Scheduled Jobs.');
            }

            action.setRedirectURL(redirectUrl);
        }
    } catch (ex) {
        illumioLogger.error('Exception: ' + ex);
        gs.addErrorMessage('Error starting deletion: ' + ex);
        action.setRedirectURL(redirectUrl);
    }
}
